body {
    margin: 0;
    padding: 0;
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
    background-color: #1a1a1a; /* Darker background for contrast */
}

canvas {
    border: 1px solid #ffffff; /* Subtle border to define the canvas */
}

js:
// Global Constants
const DIRECTION = {
    IDLE: 0,
    UP: 1,
    DOWN: 2,
    LEFT: 3,
    RIGHT: 4
};

const rounds = [5, 5, 3, 3, 2];
const colors = ['#1abc9c', '#2ecc71', '#3498db', '#e74c3c', '#9b59b6'];

// Ball Class
class Ball {
    constructor(speed, canvas) {
        this.width = 18;
        this.height = 18;
        this.x = (canvas.width / 2) - 9;
        this.y = (canvas.height / 2) - 9;
        this.moveX = DIRECTION.IDLE;
        this.moveY = DIRECTION.IDLE;
        this.speed = speed || 9;
    }
}

// Paddle Class
class Paddle {
    constructor(side, canvas) {
        this.width = 18;
        this.height = 70;
        this.x = side === 'left' ? 150 : canvas.width - 150;
        this.y = (canvas.height / 2) - 35;
        this.score = 0;
        this.move = DIRECTION.IDLE;
        this.speed = 10;
    }
}

// Pong Game Class
class Pong {
    constructor() {
        this.canvas = document.querySelector('canvas');
        this.context = this.canvas.getContext('2d');

        this.canvas.width = 1400;
        this.canvas.height = 1000;

        this.canvas.style.width = `${this.canvas.width / 2}px`;
        this.canvas.style.height = `${this.canvas.height / 2}px`;

        this.player = new Paddle('left', this.canvas);
        this.paddle = new Paddle('right', this.canvas);
        this.ball = new Ball(9, this.canvas);

        this.paddle.speed = 8;
        this.running = false;
        this.over = false;
        this.turn = this.paddle;
        this.timer = 0;
        this.round = 0;
        this.color = '#2c3e50';

        this.menu();
    }

    endGameMenu(text) {
        this.context.font = '50px Courier New';
        this.context.fillStyle = this.color;

        this.context.fillRect(
            this.canvas.width / 2 - 350,
            this.canvas.height / 2 - 48,
            700,
            100
        );

        this.context.fillStyle = '#ffffff';
        this.context.fillText(text, this.canvas.width / 2, this.canvas.height / 2 + 15);

        setTimeout(() => {
            pong = new Pong();
        }, 3000);
    }

    menu() {
        this.draw();

        this.context.font = '50px Courier New';
        this.context.fillStyle = this.color;

        this.context.fillRect(
            this.canvas.width / 2 - 350,
            this.canvas.height / 2 - 48,
            700,
            100
        );

        this.context.fillStyle = '#ffffff';
        this.context.fillText('Press any key to begin', this.canvas.width / 2, this.canvas.height / 2 + 15);
    }

    update() {
        if (!this.over) {
            if (this.ball.x <= 0) this._resetTurn(this.paddle, this.player);
            if (this.ball.x >= this.canvas.width - this.ball.width) this._resetTurn(this.player, this.paddle);
            if (this.ball.y <= 0) this.ball.moveY = DIRECTION.DOWN;
            if (this.ball.y >= this.canvas.height - this.ball.height) this.ball.moveY = DIRECTION.UP;

            if (this.player.move === DIRECTION.UP) this.player.y -= this.player.speed;
            else if (this.player.move === DIRECTION.DOWN) this.player.y += this.player.speed;

            if (this._turnDelayIsOver() && this.turn) {
                this.ball.moveX = this.turn === this.player ? DIRECTION.LEFT : DIRECTION.RIGHT;
                this.ball.moveY = [DIRECTION.UP, DIRECTION.DOWN][Math.round(Math.random())];
                this.ball.y = Math.floor(Math.random() * (this.canvas.height - 200)) + 100;
                this.turn = null;
            }

            if (this.player.y <= 0) this.player.y = 0;
            else if (this.player.y >= this.canvas.height - this.player.height) {
                this.player.y = this.canvas.height - this.player.height;
            }

            if (this.ball.moveY === DIRECTION.UP) this.ball.y -= (this.ball.speed / 1.5);
            else if (this.ball.moveY === DIRECTION.DOWN) this.ball.y += (this.ball.speed / 1.5);
            if (this.ball.moveX === DIRECTION.LEFT) this.ball.x -= this.ball.speed;
            else if (this.ball.moveX === DIRECTION.RIGHT) this.ball.x += this.ball.speed;

            if (this.paddle.y > this.ball.y - (this.paddle.height / 2)) {
                if (this.ball.moveX === DIRECTION.RIGHT) this.paddle.y -= this.paddle.speed / 1.5;
                else this.paddle.y -= this.paddle.speed / 4;
            }
            if (this.paddle.y < this.ball.y - (this.paddle.height / 2)) {
                if (this.ball.moveX === DIRECTION.RIGHT) this.paddle.y += this.paddle.speed / 1.5;
                else this.paddle.y += this.paddle.speed / 4;
            }

            if (this.paddle.y >= this.canvas.height - this.paddle.height) {
                this.paddle.y = this.canvas.height - this.paddle.height;
            } else if (this.paddle.y <= 0) this.paddle.y = 0;

            if (this.ball.x - this.ball.width <= this.player.x && this.ball.x >= this.player.x - this.player.width) {
                if (this.ball.y <= this.player.y + this.player.height && this.ball.y + this.ball.height >= this.player.y) {
                    this.ball.x = this.player.x + this.ball.width;
                    this.ball.moveX = DIRECTION.RIGHT;
                    // beep1.play();
                }
            }

            if (this.ball.x - this.ball.width <= this.paddle.x && this.ball.x >= this.paddle.x - this.paddle.width) {
                if (this.ball.y <= this.paddle.y + this.paddle.height && this.ball.y + this.ball.height >= this.paddle.y) {
                    this.ball.x = this.paddle.x - this.ball.width;
                    this.ball.moveX = DIRECTION.LEFT;
                    // beep1.play();
                }
            }
        }

        if (this.player.score === rounds[this.round]) {
            if (!rounds[this.round + 1]) {
                this.over = true;
                setTimeout(() => this.endGameMenu('Winner!'), 1000);
            } else {
                this.color = this._generateRoundColor();
                this.player.score = this.paddle.score = 0;
                this.player.speed += 0.5;
                this.paddle.speed += 1;
                this.ball.speed += 1;
                this.round += 1;
                // beep3.play();
            }
        } else if (this.paddle.score === rounds[this.round]) {
            this.over = true;
            setTimeout(() => this.endGameMenu('Game Over!'), 1000);
        }
    }

    draw() {
        this.context.clearRect(0, 0, this.canvas.width, this.canvas.height);

        this.context.fillStyle = this.color;
        this.context.fillRect(0, 0, this.canvas.width, this.canvas.height);

        this.context.fillStyle = '#ffffff';

        this.context.fillRect(this.player.x, this.player.y, this.player.width, this.player.height);
        this.context.fillRect(this.paddle.x, this.paddle.y, this.paddle.width, this.paddle.height);

        if (this._turnDelayIsOver()) {
            this.context.fillRect(this.ball.x, this.ball.y, this.ball.width, this.ball.height);
        }

        this.context.beginPath();
        this.context.setLineDash([7, 15]);
        this.context.moveTo(this.canvas.width / 2, this.canvas.height - 140);
        this.context.lineTo(this.canvas.width / 2, 140);
        this.context.lineWidth = 10;
        this.context.strokeStyle = '#ffffff';
        this.context.stroke();

        this.context.font = '100px Courier New';
        this.context.textAlign = 'center';

        this.context.fillText(this.player.score.toString(), (this.canvas.width / 2) - 300, 200);
        this.context.fillText(this.paddle.score.toString(), (this.canvas.width / 2) + 300, 200);

        this.context.font = '30px Courier New';
        this.context.fillText(`Round ${this.round + 1}`, this.canvas.width / 2, 35);

        this.context.font = '40px Courier';
        this.context.fillText(
            rounds[this.round] ? rounds[this.round] : rounds[this.round - 1],
            this.canvas.width / 2,
            100
        );
    }

    loop = () => {
        this.update();
        this.draw();
        if (!this.over) requestAnimationFrame(this.loop);
    }

    onKeyDown(key) {
        if (!this.running) {
            this.running = true;
            window.requestAnimationFrame(this.loop);
        }
        if (key.keyCode === 38 || key.keyCode === 87) this.player.move = DIRECTION.UP;
        if (key.keyCode === 40 || key.keyCode === 83) this.player.move = DIRECTION.DOWN;
    }

    onKeyUp(key) {
        this.player.move = DIRECTION.IDLE;
    }

    _resetTurn(victor, loser) {
        this.ball = new Ball(this.ball.speed, this.canvas);
        this.turn = loser;
        this.timer = Date.now();
        victor.score++;
        // beep2.play();
    }

    _turnDelayIsOver() {
        return (Date.now() - this.timer >= 1000);
    }

    _generateRoundColor() {
        const newColor = colors[Math.floor(Math.random() * colors.length)];
        return newColor === this.color ? this._generateRoundColor() : newColor;
    }
}

// Initialize the game
let pong = new Pong();

// Event Listeners
document.addEventListener('keydown', (key) => pong.onKeyDown(key));
document.addEventListener('keyup', (key) => pong.onKeyUp(key));
